"""Read persisted drift evidence; browsing never connects to a device."""
DRIFT_PAGE = r'''<!doctype html>
<html lang="zh"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Configuration drift</title><style>
:root{color-scheme:dark;--bg:#0b1220;--card:#142034;--border:#34455d;--text:#e9f2ff;--muted:#a8b9ce;--blue:#80bcff}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.5 system-ui,sans-serif}main{max-width:1600px;margin:auto;padding:28px}h1{font-size:28px;margin:8px 0}h2{font-size:20px;margin:0 0 12px}h3{font-size:16px;margin:6px 0}.bar,.filters,.actions{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.bar{justify-content:space-between}.filters{margin:20px 0;align-items:end}.field{display:flex;flex-direction:column;gap:5px}label,small,.muted{color:var(--muted)}input,select,button{font:inherit;color:var(--text);background:#0c1728;border:1px solid #4e688a;border-radius:6px;padding:8px 12px}input,select{max-width:100%}button{cursor:pointer}button:hover{background:#223956}button:disabled{opacity:.5;cursor:default}button.primary{background:#245f9a}a{color:var(--blue)}.layout{display:grid;grid-template-columns:290px minmax(0,1fr);gap:20px}.card{background:var(--card);border:1px solid var(--border);border-radius:10px;padding:20px;margin-bottom:18px}.record{display:block;width:100%;text-align:left;margin:8px 0;padding:12px}.record.active{border-color:var(--blue);background:#213c5b}.record span{display:block;font-size:12px;color:var(--muted)}.pill{padding:3px 9px;border:1px solid var(--border);border-radius:20px;display:inline-block;font-size:12px;margin-right:8px}.notice{border-left:3px solid var(--blue);padding:10px 14px;background:#19334e;margin:12px 0;white-space:pre-wrap}.error{border-color:#f5959d;background:#41242b}.facts{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:16px 0}.fact{padding:12px;background:#0e192b;border-radius:6px}.fact span{display:block}.version{font:12px ui-monospace,monospace;overflow-wrap:anywhere;color:var(--muted)}.diff{border:1px solid var(--border);border-radius:8px;margin:12px 0;overflow:hidden}.diff h3{padding:12px;overflow-wrap:anywhere}.columns{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--border)}.side{min-width:0;background:#0b1627}.side>strong{display:block;padding:8px 12px;color:var(--muted)}pre{font:12px/1.6 ui-monospace,monospace;white-space:pre-wrap;overflow-wrap:anywhere;margin:0;padding:12px;max-height:480px;overflow:auto}.line{display:block;min-height:1.6em}.removed{color:#ffb5bd;background:#552c38}.added{color:#9aebbf;background:#153d31}.actions{margin:12px 0}textarea{width:100%;min-height:90px;resize:vertical;color:var(--text);background:#0c1728;border:1px solid #4e688a;border-radius:6px;font:inherit;padding:10px}#message:empty{display:none}#message{position:sticky;top:8px;z-index:5}.group{margin-top:24px;border-bottom:1px solid var(--border);padding-bottom:8px}[hidden]{display:none!important}@media(max-width:900px){main{padding:15px}.layout{grid-template-columns:1fr}.facts,.columns{grid-template-columns:1fr}.card{padding:14px}}
</style></head><body><main>
<header class="bar"><div><small data-i="eyebrow"></small><h1 data-i="title"></h1><p class="muted" data-i="intro"></p></div><select id="language" aria-label="Language"><option value="zh">中文</option><option value="en">English</option></select></header>
<div id="message" role="status"></div>
<div class="filters"><div class="field"><label for="device" data-i="device"></label><input id="device" placeholder="Device name / UUID"></div><div class="field"><label for="status" data-i="status"></label><select id="status"><option value="open" data-i="open"></option><option value="resolved" data-i="resolved"></option><option value="all" data-i="all"></option></select></div><div class="field"><label for="origin" data-i="origin"></label><select id="origin"><option value="observed" data-i="observed"></option><option value="exercise" data-i="exercise"></option><option value="all" data-i="all"></option></select></div><label><input type="checkbox" id="unowned" checked> <span data-i="onlyUnowned"></span></label><button id="refresh" data-i="refresh"></button><label><input type="checkbox" id="autoDrift" checked> <span data-i="autoDrift"></span></label><small id="liveStatus"></small><a id="manage" data-i="manage"></a></div>
<div class="layout"><aside class="card"><h2 data-i="records"></h2><div id="recordList"></div><div class="actions"><button id="previous" data-i="previous"></button><button id="next" data-i="next"></button></div><small id="count"></small></aside><section>
<div id="empty" class="card" data-i="empty"></div><div id="detail" hidden>
<div class="card"><div class="bar"><h2 id="recordTitle"></h2><div id="badges"></div></div><div id="summary"></div><div id="times" class="facts"></div><p class="muted" data-i="binding"></p><div class="actions"><button id="full" data-i="full"></button><a id="history" data-i="history"></a></div><div id="changes"></div></div>
<div class="card"><h2 data-i="handling"></h2><p class="muted" data-i="handlingHint"></p><div id="resolution" class="notice" hidden></div><div id="handleForm"><div class="filters"><div class="field"><label for="actor" data-i="actor"></label><input id="actor" maxlength="100"></div><div class="field"><label for="reference" data-i="reference"></label><input id="reference" maxlength="100"></div></div><label for="reason" data-i="reason"></label><textarea id="reason" maxlength="1000"></textarea><div class="actions"><button class="primary" id="resolve" data-i="resolve"></button></div></div></div>
</div></section></div></main><script>
const words={zh:{eyebrow:'配置管理 / 漂移证据',title:'配置变化详情',intro:'从告警直达配置差异，保留发现时的版本证据。',device:'设备名称 / UUID（留空为全部）',status:'处理状态',origin:'记录来源',open:'未处理',resolved:'已处理',all:'全部',observed:'真实观察',exercise:'演练',onlyUnowned:'只看无主漂移',refresh:'查询 / 刷新',manage:'配置管理 ↗',records:'漂移记录',previous:'上一页',next:'下一页',empty:'没有符合条件的漂移记录。可调整设备、来源或处理状态后查询。',binding:'以下比对固定使用此记录绑定的两个版本；后续备份不会改变这次差异。配置已脱敏。时间为备份观察时间，不是实际变更执行时间。',full:'查看完整配置比对',changed:'只看变化的配置块',history:'查看此设备备份历史 ↗',handling:'登记处理结果',handlingHint:'可填写变更单 / 事件单作为处理引用。事后引用不会改变原始无主判定，也不代表事前审批；标记已处理不会恢复或修改设备配置。',actor:'处理人',reference:'关联变更单 / 事件单（可选）',reason:'处理说明（必填）',resolve:'标记已处理',required:'请填写处理人和处理说明。',confirm:'确认登记处理结果并将此漂移标为已处理？此操作不会修改设备配置。',unowned:'无匹配预登记变更',owned:'已匹配预登记变更',detected:'检测时间',before:'变更前',after:'变更后',version:'版本',created:'版本首次保存',fallback:'历史证据不足，采用版本首次保存时间',matched:'匹配的预登记变更',blocks:'变化配置块',interface:'接口',acl_policy:'ACL / 安全策略 / NAT',bgp:'BGP',other:'其他配置',added:'新增',removed:'删除',modified:'修改',unchanged:'未变化',noDiff:'没有变化的配置块',loading:'正在读取持久化证据…',failed:'读取失败，请重试',resolvedBy:'处理人',resolution:'处理说明',record:'记录',done:'已登记处理结果',item:'条'},en:{eyebrow:'Configuration / Drift evidence',title:'Configuration changes',intro:'Open the exact configuration changes behind an alert.',device:'Device name / UUID (empty = all)',status:'Handling state',origin:'Origin',open:'Open',resolved:'Resolved',all:'All',observed:'Observed',exercise:'Exercise',onlyUnowned:'Unowned only',refresh:'Query / Refresh',manage:'Configuration management ↗',records:'Drift records',previous:'Previous',next:'Next',empty:'No matching drift records. Adjust the device, origin or handling state and refresh.',binding:'Comparison uses the two versions bound to this record. Later backups do not change this evidence. Secrets are redacted. Times are backup observations, not the actual time the change was executed.',full:'Compare complete configurations',changed:'Show changed blocks only',history:'Device backup history ↗',handling:'Record handling outcome',handlingHint:'An optional change / incident reference documents the review. It does not rewrite original ownership or prove prior approval. Resolving a record does not restore or modify device configuration.',actor:'Handled by',reference:'Change / incident reference (optional)',reason:'Handling explanation (required)',resolve:'Mark resolved',required:'Enter an operator and a handling explanation.',confirm:'Record this outcome and mark the drift resolved? Device configuration will not change.',unowned:'No matching preregistered change',owned:'Matched preregistered change',detected:'Detected',before:'Before',after:'After',version:'Version',created:'Version first saved',fallback:'Legacy evidence: using version creation time',matched:'Matched preregistered change',blocks:'Changed blocks',interface:'Interfaces',acl_policy:'ACL / Security policy / NAT',bgp:'BGP',other:'Other configuration',added:'Added',removed:'Removed',modified:'Modified',unchanged:'Unchanged',noDiff:'No changed configuration blocks',loading:'Loading persisted evidence…',failed:'Unable to load; retry',resolvedBy:'Handled by',resolution:'Handling explanation',record:'Record',done:'Handling outcome recorded',item:'records'}};
const $=id=>document.getElementById(id),params=new URLSearchParams(location.search);let lang=params.get('lang')==='en'?'en':'zh',data={records:[],total:0},detail=null,offset=0,full=false,sequence=0;const limit=30,t=k=>words[lang][k]||k,fmt=n=>n?new Date(n*1000).toLocaleString(lang==='zh'?'zh-CN':'en-GB',{hour12:false}):'—';
Object.assign(words.zh,{autoDrift:'每 5 秒更新记录列表',listUpdated:'列表更新',listFailed:'列表更新失败，请刷新重试'});
Object.assign(words.en,{autoDrift:'Update record list every 5s',listUpdated:'List updated',listFailed:'List refresh failed; retry'});
function node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n}
function message(text,error=false){$('message').textContent=text;$('message').className=text?'notice'+(error?' error':''):''}
async function api(path,method='GET',body){const r=await fetch('/config'+path,{method,headers:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const j=await r.json();if(!r.ok)throw Error(j.detail||t('failed'));return j}
function link(device){return '/config/ui?'+new URLSearchParams({lang,device:device||''})}
function updateUrl(){const u=new URL(location);u.searchParams.set('lang',lang);for(const key of ['device','status','origin'])u.searchParams.set(key,$(key).value);u.searchParams.set('unowned',$('unowned').checked?'true':'false');if(detail)u.searchParams.set('id',detail.id);else u.searchParams.delete('id');history.replaceState(null,'',u)}
function renderList(){const list=$('recordList');list.replaceChildren();for(const r of data.records){const b=node('button',r.device,'record'+(detail?.id===r.id?' active':''));b.append(node('span',fmt(r.detected_at)+' · '+t(r.status)),node('span',t(r.origin)+' · '+r.changes.length+' '+t('blocks')));b.onclick=()=>choose(r.id);list.append(b)}if(!data.records.length)list.append(node('p',t('empty'),'muted'));$('count').textContent=(data.records.length?offset+1:0)+'–'+(offset+data.records.length)+' / '+data.total+' '+t('item');$('previous').disabled=offset===0;$('next').disabled=offset+data.records.length>=data.total}
function configText(v){if(v==null)return '';if(Array.isArray(v))return v.map(r=>typeof r==='string'?r:'   '.repeat((r.path||[]).length)+(r.command||JSON.stringify(r))).join('\n');return typeof v==='string'?v:JSON.stringify(v,null,2)}
function side(text,other,kind){const pre=node('pre'),counts=new Map();for(const line of other.split('\n'))counts.set(line,(counts.get(line)||0)+1);for(const line of text.split('\n')){const shared=(counts.get(line)||0)>0;if(shared)counts.set(line,counts.get(line)-1);pre.append(node('span',(shared?'  ':kind==='removed'?'- ':'+ ')+line,'line'+(!shared?' '+kind:'')))}return pre}
function renderChanges(){const box=$('changes');box.replaceChildren();const rows=full?detail.comparison:detail.changes;if(!rows?.length){box.append(node('p',t('noDiff')));return}for(const group of ['interface','acl_policy','bgp','other']){const items=rows.filter(x=>x.category===group);if(!items.length)continue;box.append(node('h2',t(group),'group'));for(const c of items){const d=node('div',undefined,'diff'),op=detail.changes.find(x=>x.context===c.context)?.operation||'unchanged';d.append(node('h3',c.context+' · '+t(op)));const cols=node('div',undefined,'columns'),a=configText(c.before),b=configText(c.after);for(const [label,text,other,kind] of [['before',a,b,'removed'],['after',b,a,'added']]){const col=node('div',undefined,'side');col.append(node('strong',t(label)),side(text,other,kind));cols.append(col)}d.append(cols);box.append(d)}}}
function renderDetail(){$('detail').hidden=!detail;$('empty').hidden=!!detail;if(!detail)return;$('recordTitle').textContent=detail.device;$('badges').replaceChildren(...[t(detail.status),t(detail.origin),t(detail.unowned?'unowned':'owned')].map(v=>node('span',v,'pill')));$('summary').replaceChildren(node('p',t('detected')+': '+fmt(detail.detected_at)+' · '+detail.changes.length+' '+t('blocks')),node('small',t('record')+': '+detail.id));if(detail.change_ref)$('summary').append(node('p',t('matched')+': '+detail.change_ref));const times=$('times');times.replaceChildren();for(const key of ['before','after']){const v=detail[key],n=node('div',undefined,'fact');n.append(node('strong',t(key)),node('span',fmt(v.observed_at)),node('span',t('version')+': '+v.id,'version'));if(v.observation_basis==='version_creation')n.append(node('small',t('fallback')));times.append(n)}$('full').textContent=t(full?'changed':'full');$('history').href=link(detail.device_id);renderChanges();$('handleForm').hidden=detail.status==='resolved';$('resolution').hidden=detail.status!=='resolved';$('resolution').textContent=t('resolvedBy')+': '+(detail.resolved_by||'—')+' · '+fmt(detail.resolved_at)+'\n'+t('resolution')+': '+(detail.resolution||'—')}
function translate(){document.documentElement.lang=lang;document.querySelectorAll('[data-i]').forEach(n=>n.textContent=t(n.dataset.i));$('language').value=lang;$('manage').href=link($('device').value);renderList();renderDetail()}
async function choose(id){const turn=++sequence;message(t('loading'));detail=null;full=false;renderDetail();try{const value=await api('/drift/'+encodeURIComponent(id));if(turn!==sequence)return;detail=value;$('reason').value='';$('reference').value='';renderList();renderDetail();updateUrl();message('')}catch(e){if(turn===sequence)message(e.message,true)}}
async function load(reset=true,selected=null){const turn=++sequence;if(reset)offset=0;message(t('loading'));detail=null;full=false;renderDetail();const q=new URLSearchParams({limit,offset});if($('device').value.trim())q.set('device',$('device').value.trim());for(const key of ['status','origin'])if($(key).value!=='all')q.set(key,$(key).value);if($('unowned').checked)q.set('unowned','true');try{const value=await api('/drift?'+q);if(turn!==sequence)return;data=value;renderList();updateUrl();$('manage').href=link($('device').value);if(selected||data.records.length)await choose(selected||data.records[0].id);else message('')}catch(e){if(turn===sequence){data={records:[],total:0};renderList();message(e.message,true)}}}
$('device').value=params.get('device')||'';for(const key of ['status','origin'])if([...$(key).options].some(o=>o.value===params.get(key)))$(key).value=params.get(key);$('unowned').checked=params.get('unowned')!=='false';
$('language').onchange=()=>{lang=$('language').value;translate();updateUrl()};$('refresh').onclick=()=>load();$('previous').onclick=()=>{offset=Math.max(0,offset-limit);load(false)};$('next').onclick=()=>{offset+=limit;load(false)};
$('full').onclick=async()=>{if(!detail)return;if(full){full=false;renderDetail();return}const id=detail.id,turn=sequence;$('full').disabled=true;try{const v=detail.comparison?detail:await api('/drift/'+encodeURIComponent(id)+'?full=true');if(turn!==sequence||detail?.id!==id)return;detail=v;full=true;renderDetail();message('')}catch(e){message(e.message,true)}finally{$('full').disabled=false}};
$('resolve').onclick=async()=>{if(!detail||detail.status!=='open')return;const actor=$('actor').value.trim(),reason=$('reason').value.trim(),reference=$('reference').value.trim();if(!actor||!reason){message(t('required'),true);return}if(!confirm(t('confirm')))return;const id=detail.id,turn=sequence;$('resolve').disabled=true;try{await api('/drift/'+encodeURIComponent(id)+'/resolve','POST',{actor,reason,reference:reference||null});if(turn!==sequence)return;await load(false,id);message(t('done'))}catch(e){message(e.message,true)}finally{$('resolve').disabled=false}};
let listPolling=false;
async function refreshList(){if(listPolling||document.hidden||!$('autoDrift').checked||$('resolve').disabled)return;const turn=sequence,selectedFilters=[$('device').value,$('status').value,$('origin').value,$('unowned').checked,offset].join('|');const q=new URLSearchParams({limit,offset});if($('device').value.trim())q.set('device',$('device').value.trim());for(const key of ['status','origin'])if($(key).value!=='all')q.set(key,$(key).value);if($('unowned').checked)q.set('unowned','true');listPolling=true;try{const value=await api('/drift?'+q);if(turn!==sequence||selectedFilters!==[$('device').value,$('status').value,$('origin').value,$('unowned').checked,offset].join('|'))return;if(JSON.stringify(value)!==JSON.stringify(data)){data=value;renderList();if(!detail&&data.records.length)await choose(data.records[0].id)}$('liveStatus').textContent=t('listUpdated')+': '+fmt(Date.now()/1000)}catch(e){$('liveStatus').textContent=t('listFailed')}finally{listPolling=false}}
setInterval(refreshList,5000);
translate();load(true,params.get('id'));
</script></body></html>'''
